    {
      "kind": "commitment",
      "content": "调查员明确今日不接新委托、不作新承诺，仅请各方保留目前可核实的记录。",
      "recipients": ["npc:tailor"],
      "speaker_id": "player"
    },
    {
      "kind": "statement",
      "content": "马丁同意将订单簿收据、数日时间顺序与谈过的处理边界各自留着，未再催委托或报酬。",
      "recipients": ["player"],
      "speaker_id": "npc:tailor"
    }
  ]
}
